const payScheduleInvestorCoupons = `-- name: PayScheduleInvestorCoupons :one
WITH paid AS (
    UPDATE investor_coupon_schedule
    SET coupon_status = 1, coupon_paid_value = coupon_value, payment_settlement_date = $2, updated_by = $3::text
    WHERE bond_coupon_schedule_id = $1 AND deleted_at IS NULL AND COALESCE(coupon_status, 0) = 0
    RETURNING coupon_value)
SELECT COALESCE(sum(coupon_value), 0)::numeric AS total FROM paid
`

type PayScheduleInvestorCouponsParams struct {
	BondCouponScheduleID  *int64
	PaymentSettlementDate *time.Time
	Column3               string
}

func (q *Queries) PayScheduleInvestorCoupons(ctx context.Context, arg PayScheduleInvestorCouponsParams) (decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, payScheduleInvestorCoupons, arg.BondCouponScheduleID, arg.PaymentSettlementDate, arg.Column3)
	var total decimal.Decimal
	err := row.Scan(&total)
	return total, err
}

const refreshBondCouponDates = `-- name: RefreshBondCouponDates :exec
UPDATE bond
SET next_coupon_date = (SELECT min(s.coupon_date) FROM bond_coupon_schedule s
                        WHERE s.bond_id = $1 AND s.deleted_at IS NULL AND COALESCE(s.status, 0) = 0),
    last_coupon_date = (SELECT max(s.coupon_date) FROM bond_coupon_schedule s
                        WHERE s.bond_id = $1 AND s.deleted_at IS NULL AND s.status = 1)
WHERE id = $1
`

func (q *Queries) RefreshBondCouponDates(ctx context.Context, bondID *int64) error {
	_, err := q.db.Exec(ctx, refreshBondCouponDates, bondID)
	return err
}

